using System.Net;
using System.Text;
namespace Terraplenagem.IFM;
public static class Report {
 public static void Html(string path,Project p,Result r){
  string H(object? s)=>WebUtility.HtmlEncode(s?.ToString()) ?? "";string N(double v)=>v.ToString("N3",System.Globalization.CultureInfo.GetCultureInfo("pt-BR"));
  var sb=new StringBuilder("<!doctype html><html lang='pt-BR'><meta charset='utf-8'><title>DISTRIBUIÇÃO DE TERRAPLENAGEM — IFM</title><style>body{font:15px Arial;margin:35px;color:#203140}table{border-collapse:collapse;width:100%;margin:16px 0}td,th{padding:7px;border:1px solid #bbc}th{background:#e5f1ef}h1{color:#14685f}@media print{body{margin:12mm}}</style><h1>DISTRIBUIÇÃO DE TERRAPLENAGEM — IFM</h1>");
  sb.Append($"<h2>{H(p.Nome)}</h2><p>Fonte: {H(p.Fonte)}. Objetivo: {(p.UsarCustos?"menor custo por faixa":p.MinimizarExtraordinario?"menor momento extraordinário":"menor momento total")}, após minimizar as pendências de cortes e aterros em volume de banco. Fatores de homogeneização e propriedades dos materiais são informados pelo usuário.</p><p>Distribuído: {N(r.Distribuido_m3)} m³ de banco. Momento total: {N(r.Movimentos.Sum(x=>x.Momento_m3_km))} m³·km. Momento extraordinário: {N(r.Movimentos.Sum(x=>x.Extraordinario_m3_km))} m³·km. Franquia: {N(p.Franquia_m)} m. Estimativa de custo: {N(r.Movimentos.Sum(x=>x.Custo))}.</p>");
  if(p.CompensacaoLateral.Count>0){sb.Append($"<h2>Compensação lateral assumida por intervalo</h2><p>{N(p.CompensacaoLateral.Sum(x=>x.Banco_m3))} m³ de banco; {N(p.CompensacaoLateral.Sum(x=>x.Aterro_geometrico_m3))} m³ geométricos. Excluída do transporte longitudinal acima. Hipótese confirmada pelo usuário: todo corte é compatível com o aterro local. Distância longitudinal zero não significa transporte transversal sem custo.</p><table><tr><th>Início (m)</th><th>Fim (m)</th><th>Banco (m³)</th><th>Aterro geométrico (m³)</th></tr>");foreach(var x in p.CompensacaoLateral)sb.Append($"<tr><td>{N(x.Inicio_m)}</td><td>{N(x.Fim_m)}</td><td>{N(x.Banco_m3)}</td><td>{N(x.Aterro_geometrico_m3)}</td></tr>");sb.Append("</table>");}
  sb.Append(Bruckner.Svg(p));
  sb.Append("<h2>Quadro de distribuição</h2><table><tr><th>Origem</th><th>Destino</th><th>Categoria</th><th>Banco (m³)</th><th>Geométrico (m³)</th><th>DMT (m)</th><th>Momento (m³·km)</th></tr>");
  foreach(var m in r.Movimentos)sb.Append($"<tr><td>{H(m.Origem)}</td><td>{H(m.Destino)}</td><td>{m.Categoria}</td><td>{N(m.Banco_m3)}</td><td>{N(m.Geometrico_m3)}</td><td>{N(m.DMT_m)}</td><td>{N(m.Momento_m3_km)}</td></tr>");sb.Append("</table><h2>Escavação, carga e transporte por categoria e faixa</h2><table><tr><th>Categoria</th><th>Faixa</th><th>Banco (m³)</th><th>DMT ponderada (m)</th><th>Extraordinário (m³·km)</th><th>Custo estimado</th></tr>");
  foreach(var g in r.Movimentos.GroupBy(m=>(m.Categoria,m.Faixa)))sb.Append($"<tr><td>{g.Key.Categoria}</td><td>{H(g.Key.Faixa)}</td><td>{N(g.Sum(x=>x.Banco_m3))}</td><td>{N(g.Sum(x=>x.Banco_m3*x.DMT_m)/g.Sum(x=>x.Banco_m3))}</td><td>{N(g.Sum(x=>x.Extraordinario_m3_km))}</td><td>{N(g.Sum(x=>x.Custo))}</td></tr>");
  sb.Append("</table><h2>Aterros por energia informada</h2><table><tr><th>Energia</th><th>Geométrico atendido (m³)</th></tr>");foreach(var g in r.Movimentos.Where(m=>!m.ADME).GroupBy(m=>m.Energia))sb.Append($"<tr><td>{H(g.Key)}</td><td>{N(g.Sum(x=>x.Geometrico_m3))}</td></tr>");
  sb.Append("</table><h2>Pendências e reservas</h2><table><tr><th>Item</th><th>Situação</th><th>Banco (m³)</th><th>Geométrico (m³)</th></tr>");foreach(var x in r.Pendencias)sb.Append($"<tr><td>{H(x.Nome)}</td><td>{H(x.Situacao)}</td><td>{N(x.Banco_m3)}</td><td>{N(x.Geometrico_m3)}</td></tr>");sb.Append("</table><h2>Entradas e rastreabilidade</h2><p>Os números abaixo são entradas do cenário, sem certificação automática de adequação geotécnica. ADME tem capacidade em banco; os aterros usam volume geométrico × fator banco/geométrico. Custos são por m³ de banco na faixa inteira, sem tarifa marginal.</p><pre>");sb.Append(H(System.Text.Json.JsonSerializer.Serialize(p,Files.JsonOptions)));sb.Append("</pre></html>");File.WriteAllText(path,sb.ToString(),Encoding.UTF8);
 }
}
